-#define MAX(a, b) ((a) > (b) ? (a) : (b))
-#define MIN(a, b) ((a) < (b) ? (a) : (b))
-
-namespace vllm {
-namespace moe {
-
-template <typename HashIndType>
-__device__ __forceinline__ int64_t load_index_as_int64(const HashIndType* ptr,
-                                                       int64_t offset) {
-  return static_cast<int64_t>(ptr[offset]);
-}
-
-/// Aligned array type
-template <typename T,
-          /// Number of elements in the array
-          int N,
-          /// Alignment requirement in bytes
-          int Alignment = sizeof(T) * N>
-struct alignas(Alignment) AlignedArray {
-  T data[N];
-};
-
-template <typename T>
-__device__ __forceinline__ float toFloat(T value) {
-  if constexpr (std::is_same_v<T, float>) {
-    return value;
-  } else if constexpr (std::is_same_v<T, __nv_bfloat16>) {
-    return __bfloat162float(value);
-  } else if constexpr (std::is_same_v<T, __half>) {
-    return __half2float(value);
-  }
-}
-
-#ifndef USE_ROCM
-// Adapted from:
-// https://github.com/sgl-project/sglang/blob/main/python/sglang/jit_kernel/csrc/deepseek_v4/hash_topk.cuh
-template <typename OutIndType, typename HashIndType>
-__launch_bounds__(128) __global__
-    void dsv4HashTopkSoftplusSqrt(const float* input, float* output,
-                                  OutIndType* indices, int num_rows,
-                                  int num_experts, float routed_scaling_factor,
-                                  const HashIndType* input_ids,
-                                  const HashIndType* tid2eid,
-                                  const bool* is_padding, const float* bias_vl,
-                                  int64_t image_sentinel_lo) {
-  const int warp = (blockIdx.x * blockDim.x + threadIdx.x) / 32;
-  const int lane = threadIdx.x % 32;
-  if (warp >= num_rows) return;
-  const int64_t token_id = load_index_as_int64(input_ids, warp);
-  const bool is_pad_row = is_padding != nullptr && is_padding[warp];
-  // Image tokens carry five consecutive in-vocab sentinel ids starting at
-  // image_sentinel_lo (0 = disabled); they skip the tid2eid lookup and
-  // select experts by score + bias_vl instead. Ids above the sentinel block
-  // are regular special tokens and must not match.
-  const bool is_image = bias_vl != nullptr && image_sentinel_lo > 0 &&
-                        token_id >= image_sentinel_lo &&
-                        token_id < image_sentinel_lo + 5;
-
-  #if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaGridDependencySynchronize();
-  #endif
-  int expert = 0;
-  float weight = 0.f;
-  if (is_image && !is_pad_row) {
-    // Top-6 by (sqrtsoftplus(x) + bias_vl) over the full row; the routing
-    // weights are the raw sqrtsoftplus scores of the selected experts.
-    constexpr int MAX_PER_LANE = 12;  // supports num_experts <= 384
-    const int per_lane = num_experts / 32;
-    float vals[MAX_PER_LANE];
-    float sels[MAX_PER_LANE];
-  #pragma unroll
-    for (int i = 0; i < MAX_PER_LANE; ++i) {
-      if (i < per_lane) {
-        const int e = lane + 32 * i;
-        const float x = input[warp * num_experts + e];
-        float v = sqrtf(fmaxf(x, 0.f) + __logf(1.f + __expf(-fabsf(x))));
-        if (isnan(v)) {
-          v = 0.f;
-        }
-        vals[i] = v;
-        sels[i] = v + bias_vl[e];
-      } else {
-        vals[i] = 0.f;
-        sels[i] = -INFINITY;
-      }
-    }
-    int slot_expert[6];
-    float slot_weight[6];
-  #pragma unroll
-    for (int j = 0; j < 6; ++j) {
-      float best = -INFINITY;
-      int best_e = num_experts;
-  #pragma unroll
-      for (int i = 0; i < MAX_PER_LANE; ++i) {
-        if (sels[i] > best) {
-          best = sels[i];
-          best_e = lane + 32 * i;
-        }
-      }
-      // Warp argmax reduce; ties go to the lower expert id.
-  #pragma unroll
-      for (int mask = 16; mask > 0; mask >>= 1) {
-        const float other_best = VLLM_SHFL_XOR_SYNC(best, mask);
-        const int other_e = VLLM_SHFL_XOR_SYNC(best_e, mask);
-        if (other_best > best || (other_best == best && other_e < best_e)) {
-          best = other_best;
-          best_e = other_e;
-        }
-      }
-      float w = 0.f;
-  #pragma unroll
-      for (int i = 0; i < MAX_PER_LANE; ++i) {
-        if (lane + 32 * i == best_e) {
-          w = vals[i];
-          sels[i] = -INFINITY;
-        }
-      }
-  #pragma unroll
-      for (int mask = 16; mask > 0; mask >>= 1) {
-        w += VLLM_SHFL_XOR_SYNC(w, mask);
-      }
-      slot_expert[j] = best_e;
-      slot_weight[j] = w;
-    }
-    if (lane < 6) {
-      expert = slot_expert[lane];
-      weight = slot_weight[lane];
-    }
-  } else if (lane < 6 && !is_pad_row) {
-    // only load and calculate for 6 experts
-    expert = static_cast<int>(tid2eid[token_id * 6 + lane]);
-    const float x = input[warp * num_experts + expert];
-    weight = sqrtf(fmaxf(x, 0.f) + __logf(1.f + __expf(-fabsf(x))));
-    if (isnan(weight)) {
-      weight = 0.f;
-    }
-  }
-  float weight_sum = weight;
-  #pragma unroll
-  for (int mask = 16; mask > 0; mask >>= 1) {
-    // sum in warp
-    weight_sum += VLLM_SHFL_XOR_SYNC(weight_sum, mask);
-  }
-
-  #if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaTriggerProgrammaticLaunchCompletion();
-  #endif
-  if (lane < 6) {
-    const int offset = warp * 6 + lane;
-    output[offset] =
-        weight * routed_scaling_factor / (weight_sum > 0.f ? weight_sum : 1.f);
-    indices[offset] = !is_pad_row ? static_cast<OutIndType>(expert)
-                                  : static_cast<OutIndType>(-1);
-  }
-}
-
-template <typename OutIndType, typename HashIndType>
-void launchDsv4HashTopk(const float* input, float* output, OutIndType* indices,
-                        int num_rows, int num_experts,
-                        double routed_scaling_factor,
-                        const HashIndType* input_ids,
-                        const HashIndType* tid2eid, cudaStream_t stream,
-                        const bool* is_padding, const float* bias_vl,
-                        int64_t image_sentinel_lo) {
-  if (num_rows == 0) return;
-  auto* kernel = &dsv4HashTopkSoftplusSqrt<OutIndType, HashIndType>;
-  cudaLaunchConfig_t config = {};
-  config.gridDim = (num_rows + 3) / 4;
-  config.blockDim = 128;
-  config.stream = stream;
-  cudaLaunchAttribute attr;
-  attr.id = cudaLaunchAttributeProgrammaticStreamSerialization;
-  attr.val.programmaticStreamSerializationAllowed = 1;
-  config.attrs = &attr;
-  config.numAttrs = 1;
-  const float scale = static_cast<float>(routed_scaling_factor);
-  cudaLaunchKernelEx(&config, kernel, input, output, indices, num_rows,
-                     num_experts, scale, input_ids, tid2eid, is_padding,
-                     bias_vl, image_sentinel_lo);
-}
-#endif
-
-// ====================== TopK softplus_sqrt things
-// ===============================
-
-/*
-  A Top-K gating softplus_sqrt written to exploit when the number of experts in
-  the MoE layers are a small power of 2. This allows us to cleanly share the
-  rows among the threads in a single warp and eliminate communication between
-  warps (so no need to use shared mem).
-
-  It fuses the sigmoid, max and argmax into a single kernel.
-
-  Limitations:
-  1) This implementation is optimized for when the number of experts is a small
-  power of 2. Additionally it also supports when number of experts is multiple
-  of 64 which is still faster than the computing sigmoid and topK separately
-  (only tested on CUDA yet). 2) This implementation assumes k is small, but will
-  work for any k.
-*/
-
-template <int VPT, int NUM_EXPERTS, int WARPS_PER_CTA, int BYTES_PER_LDG,
-          int WARP_SIZE_PARAM, bool USE_HASH, typename IndType,
-          typename HashIndType, typename InputType = float>
-__launch_bounds__(WARPS_PER_CTA* WARP_SIZE_PARAM) __global__
-    void topkGatingSoftplusSqrt(
-        const InputType* input, const bool* finished, float* output,
-        const int num_rows, IndType* indices, int* source_rows, const int k,
-        const int start_expert, const int end_expert, const bool renormalize,
-        double routed_scaling_factor, const float* correction_bias,
-        const HashIndType* input_ids, const HashIndType* tid2eid,
-        const bool* is_padding, const float* bias_vl,
-        int64_t image_sentinel_lo) {
-  static_assert(std::is_same_v<InputType, float> ||
-                    std::is_same_v<InputType, __nv_bfloat16> ||
-                    std::is_same_v<InputType, __half>,
-                "InputType must be float, __nv_bfloat16, or __half");
-
-  // We begin by enforcing compile time assertions and setting up compile time
-  // constants.
-  static_assert(BYTES_PER_LDG == (BYTES_PER_LDG & -BYTES_PER_LDG),
-                "BYTES_PER_LDG must be power of 2");
-  static_assert(BYTES_PER_LDG <= 16, "BYTES_PER_LDG must be leq 16");
-
-  // Number of bytes each thread pulls in per load
-  static constexpr int ELTS_PER_LDG = BYTES_PER_LDG / sizeof(InputType);
-  static constexpr int ELTS_PER_ROW = NUM_EXPERTS;
-  static constexpr int THREADS_PER_ROW = ELTS_PER_ROW / VPT;
-  static constexpr int LDG_PER_THREAD = VPT / ELTS_PER_LDG;
-
-  if constexpr (std::is_same_v<InputType, __nv_bfloat16> ||
-                std::is_same_v<InputType, __half>) {
-    static_assert(ELTS_PER_LDG == 1 || ELTS_PER_LDG % 2 == 0,
-                  "ELTS_PER_LDG must be 1 or even for 16-bit conversion");
-  }
-
-  // Restrictions based on previous section.
-  static_assert(
-      VPT % ELTS_PER_LDG == 0,
-      "The elements per thread must be a multiple of the elements per ldg");
-  static_assert(WARP_SIZE_PARAM % THREADS_PER_ROW == 0,
-                "The threads per row must cleanly divide the threads per warp");
-  static_assert(THREADS_PER_ROW == (THREADS_PER_ROW & -THREADS_PER_ROW),
-                "THREADS_PER_ROW must be power of 2");
-  static_assert(THREADS_PER_ROW <= WARP_SIZE_PARAM,
-                "THREADS_PER_ROW can be at most warp size");
-
-  // We have NUM_EXPERTS elements per row. We specialize for small #experts
-  static constexpr int ELTS_PER_WARP = WARP_SIZE_PARAM * VPT;
-  static constexpr int ROWS_PER_WARP = ELTS_PER_WARP / ELTS_PER_ROW;
-  static constexpr int ROWS_PER_CTA = WARPS_PER_CTA * ROWS_PER_WARP;
-
-  // Restrictions for previous section.
-  static_assert(ELTS_PER_WARP % ELTS_PER_ROW == 0,
-                "The elts per row must cleanly divide the total elt per warp");
-
-  // ===================== From this point, we finally start computing run-time
-  // variables. ========================
-
-  // Compute CTA and warp rows. We pack multiple rows into a single warp, and a
-  // block contains WARPS_PER_CTA warps. This, each block processes a chunk of
-  // rows. We start by computing the start row for each block.
-  const int cta_base_row = blockIdx.x * ROWS_PER_CTA;
-
-  // Now, using the base row per thread block, we compute the base row per warp.
-  const int warp_base_row = cta_base_row + threadIdx.y * ROWS_PER_WARP;
-
-  // The threads in a warp are split into sub-groups that will work on a row.
-  // We compute row offset for each thread sub-group
-  const int thread_row_in_warp = threadIdx.x / THREADS_PER_ROW;
-  const int thread_row = warp_base_row + thread_row_in_warp;
-
-  // Threads with indices out of bounds should early exit here.
-  if (thread_row >= num_rows) {
-    return;
-  }
-  const bool row_is_active = finished ? !finished[thread_row] : true;
-  const bool is_pad_row = is_padding != nullptr && is_padding[thread_row];
-
-  // Image tokens carry five consecutive in-vocab sentinel ids starting at
-  // image_sentinel_lo (0 = disabled); they select experts with bias_vl
-  // instead of correction_bias / the tid2eid hash table. Ids above the
-  // sentinel block are regular special tokens and must not match.
-  int64_t token_id = 0;
-  if (input_ids != nullptr) {
-    token_id = load_index_as_int64(input_ids, thread_row);
-  }
-  const bool use_vl_bias = bias_vl != nullptr && image_sentinel_lo > 0 &&
-                           token_id >= image_sentinel_lo &&
-                           token_id < image_sentinel_lo + 5;
-  const float* row_bias = use_vl_bias ? bias_vl : correction_bias;
-
-  // We finally start setting up the read pointers for each thread. First, each
-  // thread jumps to the start of the row it will read.
-  const InputType* thread_row_ptr = input + thread_row * ELTS_PER_ROW;
-
-  // Now, we compute the group each thread belong to in order to determine the
-  // first column to start loads.
-  const int thread_group_idx = threadIdx.x % THREADS_PER_ROW;
-  const int first_elt_read_by_thread = thread_group_idx * ELTS_PER_LDG;
-  const InputType* thread_read_ptr = thread_row_ptr + first_elt_read_by_thread;
-
-  // Finally, we pull in the data from global mem
-  float row_chunk[VPT];
-
-#if (defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900))
-  cudaGridDependencySynchronize();
-#endif
-
-  if (is_pad_row) {
-#pragma unroll
-    for (int ii = 0; ii < VPT; ++ii) {
-      row_chunk[ii] = 0.f;
-    }
-  } else if constexpr (std::is_same_v<InputType, float>) {
-    using VecType = AlignedArray<float, ELTS_PER_LDG>;
-    VecType* row_chunk_vec_ptr = reinterpret_cast<VecType*>(&row_chunk);
-    const VecType* vec_thread_read_ptr =
-        reinterpret_cast<const VecType*>(thread_read_ptr);
-#pragma unroll
-    for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
-      row_chunk_vec_ptr[ii] = vec_thread_read_ptr[ii * THREADS_PER_ROW];
-    }
-  } else if constexpr (std::is_same_v<InputType, __nv_bfloat16>) {
-    if constexpr (ELTS_PER_LDG >= 2) {
-      using VecType = AlignedArray<__nv_bfloat16, ELTS_PER_LDG>;
-      float2* row_chunk_f2 = reinterpret_cast<float2*>(row_chunk);
-      const VecType* vec_thread_read_ptr =
-          reinterpret_cast<const VecType*>(thread_read_ptr);
-#pragma unroll
-      for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
-        VecType vec = vec_thread_read_ptr[ii * THREADS_PER_ROW];
-        int base_idx_f2 = ii * ELTS_PER_LDG / 2;
-#pragma unroll
-        for (int jj = 0; jj < ELTS_PER_LDG / 2; ++jj) {
-          row_chunk_f2[base_idx_f2 + jj] = __bfloat1622float2(
-              *reinterpret_cast<const __nv_bfloat162*>(vec.data + jj * 2));
-        }
-      }
-    } else {  // ELTS_PER_LDG == 1
-#pragma unroll
-      for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
-        const __nv_bfloat16* scalar_ptr =
-            thread_read_ptr + ii * THREADS_PER_ROW;
-        row_chunk[ii] = __bfloat162float(*scalar_ptr);
-      }
-    }
-  } else if constexpr (std::is_same_v<InputType, __half>) {
-    if constexpr (ELTS_PER_LDG >= 2) {
-      using VecType = AlignedArray<__half, ELTS_PER_LDG>;
-      float2* row_chunk_f2 = reinterpret_cast<float2*>(row_chunk);
-      const VecType* vec_thread_read_ptr =
-          reinterpret_cast<const VecType*>(thread_read_ptr);
-#pragma unroll
-      for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
-        VecType vec = vec_thread_read_ptr[ii * THREADS_PER_ROW];
-        int base_idx_f2 = ii * ELTS_PER_LDG / 2;
-#pragma unroll
-        for (int jj = 0; jj < ELTS_PER_LDG / 2; ++jj) {
-          row_chunk_f2[base_idx_f2 + jj] = __half22float2(
-              *reinterpret_cast<const __half2*>(vec.data + jj * 2));
-        }
-      }
-    } else {  // ELTS_PER_LDG == 1
-#pragma unroll
-      for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
-        const __half* scalar_ptr = thread_read_ptr + ii * THREADS_PER_ROW;
-        row_chunk[ii] = __half2float(*scalar_ptr);
-      }
-    }
-  }
-  constexpr float threshold = 20.0f;
-  constexpr float beta = 1.0f;
-
-  // Hash MoE path: indices are predetermined from lookup table. Image rows
-  // (sentinel ids) fall through to the score-based top-k path with bias_vl.
-  const bool hash_row = USE_HASH && !use_vl_bias;
-  if (hash_row) {
-    const int64_t token_expert_offset = token_id * static_cast<int64_t>(k);
-    if (!is_pad_row) {
-#pragma unroll
-      for (int ii = 0; ii < VPT; ++ii) {
-        float val = row_chunk[ii];
-        float val_b = val * beta;
-        val = (val_b > threshold) ? val : (__logf(1.0f + __expf(val_b))) / beta;
-        val = sqrtf(val);
-
-        // Dummy/padding tokens can result in NaN values, so
-        // clamp them to 0.0. Note: this clamp could likely be removed if
-        // 'is_padding' is made mandatory
-        if (isnan(val)) {
-          val = 0.f;
-        }
-        row_chunk[ii] = val;
-      }
-    }
-    float selected_sum = 0.f;
-#pragma unroll
-    for (int k_idx = 0; k_idx < k; ++k_idx) {
-      const int expert = static_cast<int>(
-          load_index_as_int64(tid2eid, token_expert_offset + k_idx));
-      const int idx = k * thread_row + k_idx;
-      for (int ii = 0; ii < VPT; ++ii) {
-        const int group_id = ii / ELTS_PER_LDG;
-        const int local_id = ii % ELTS_PER_LDG;
-        const int expert_idx = first_elt_read_by_thread +
-                               group_id * THREADS_PER_ROW * ELTS_PER_LDG +
-                               local_id;
-        if (expert == expert_idx) {
-          indices[idx] = !is_pad_row ? static_cast<IndType>(expert)
-                                     : static_cast<IndType>(-1);
-          selected_sum += row_chunk[ii];
-          break;
-        }
-      }
-    }
-    // Compute per-thread scale (using warp reduction when renormalizing).
-    // THREADS_PER_ROW-parameterized butterfly works for both warp sizes (32
-    // on CUDA, 64 on ROCm CDNA) and any THREADS_PER_ROW the dispatch picks.
-    if (renormalize) {
-#pragma unroll
-      for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
-        selected_sum +=
-            VLLM_SHFL_XOR_SYNC_WIDTH(selected_sum, mask, THREADS_PER_ROW);
-      }
-    }
-    float scale = static_cast<float>(routed_scaling_factor);
-    if (renormalize) {
-      const float denom = selected_sum > 0.f ? selected_sum : 1.f;
-      scale /= denom;
-    }
-
-#pragma unroll
-    for (int k_idx = 0; k_idx < k; ++k_idx) {
-      const int expert = static_cast<int>(
-          load_index_as_int64(tid2eid, token_expert_offset + k_idx));
-      const int idx = k * thread_row + k_idx;
-      for (int ii = 0; ii < VPT; ++ii) {
-        const int group_id = ii / ELTS_PER_LDG;
-        const int local_id = ii % ELTS_PER_LDG;
-        const int expert_idx = first_elt_read_by_thread +
-                               group_id * THREADS_PER_ROW * ELTS_PER_LDG +
-                               local_id;
-        if (expert == expert_idx) {
-          output[idx] = row_chunk[ii] * scale;
-          break;
-        }
-      }
-    }
-#if (defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900))
-    cudaTriggerProgrammaticLaunchCompletion();
-#endif
-    return;
-  } else {
-    if (!is_pad_row) {
-#pragma unroll
-      for (int ii = 0; ii < VPT; ++ii) {
-        float val = row_chunk[ii];
-        float val_b = val * beta;
-        // Compute softplus: log(1 + exp(val)) with numerical stability
-        // When val > threshold, softplus(x) ≈ x to avoid exp overflow
-        val = (val_b > threshold) ? val : (__logf(1.0f + __expf(val_b))) / beta;
-        val = sqrtf(val);
-        // Dummy/padding tokens can result in NaN values, so
-        // clamp them to 0.0. Note: this clamp could likely be removed if
-        // 'is_padding' is made mandatory
-        if (isnan(val)) {
-          val = 0.f;
-        }
-        if (row_bias) {
-          const int group_id = ii / ELTS_PER_LDG;
-          const int local_id = ii % ELTS_PER_LDG;
-          const int expert_idx = first_elt_read_by_thread +
-                                 group_id * THREADS_PER_ROW * ELTS_PER_LDG +
-                                 local_id;
-          val = val + row_bias[expert_idx];
-        }
-        row_chunk[ii] = val;
-      }
-    }
-
-    // Original TopK path: find top-k experts by score
-    // Now, sigmoid_res contains the sigmoid of the row chunk. Now, I want to
-    // find the topk elements in each row, along with the max index.
-    int start_col = first_elt_read_by_thread;
-    static constexpr int COLS_PER_GROUP_LDG = ELTS_PER_LDG * THREADS_PER_ROW;
-
-    float selected_sum = 0.f;
-    for (int k_idx = 0; k_idx < k; ++k_idx) {
-      // First, each thread does the local argmax
-      float max_val = row_chunk[0];
-      int expert = start_col;
-#pragma unroll
-      for (int ldg = 0, col = start_col; ldg < LDG_PER_THREAD;
-           ++ldg, col += COLS_PER_GROUP_LDG) {
-#pragma unroll
-        for (int ii = 0; ii < ELTS_PER_LDG; ++ii) {
-          float val = row_chunk[ldg * ELTS_PER_LDG + ii];
-
-          // No check on the experts here since columns with the smallest index
-          // are processed first and only updated if > (not >=)
-          if (val > max_val) {
-            max_val = val;
-            expert = col + ii;
-          }
-        }
-      }
-
-// Now, we perform the argmax reduce. We use the butterfly pattern so threads
-// reach consensus about the max. This will be useful for K > 1 so that the
